import { Vec3 } from "./Vec3.js";

export class Mat3 {
	// Fields are `declare`d instead of parameter properties so no class fields
	// are emitted (see the note in `Vec2`).
	/** Column 0 of the matrix (the `x` axis). */
	declare xAxis: Vec3;
	/** Column 1 of the matrix (the `y` axis). */
	declare yAxis: Vec3;
	/** Column 2 of the matrix (the `z` axis). */
	declare zAxis: Vec3;

	constructor(xAxis: Vec3, yAxis: Vec3, zAxis: Vec3) {
		this.xAxis = xAxis;
		this.yAxis = yAxis;
		this.zAxis = zAxis;
	}

	/**
	 * Creates a new `Mat3` from multiple values.
	 */
	static new(
		m00: number,
		m01: number,
		m02: number,
		m10: number,
		m11: number,
		m12: number,
		m20: number,
		m21: number,
		m22: number,
	): Mat3 {
		return new Mat3(
			new Vec3(m00, m01, m02),
			new Vec3(m10, m11, m12),
			new Vec3(m20, m21, m22),
		);
	}

	/** All zeroes. (0, 0..) */
	static get ZERO() {
		return new Mat3(new Vec3(0, 0, 0), new Vec3(0, 0, 0), new Vec3(0, 0, 0));
	}

	/** All `Identity`, where all diagonal elements are `1`, and all off-diagonal elements are `0`. */
	static get IDENTITY() {
		return new Mat3(new Vec3(1, 0, 0), new Vec3(0, 1, 0), new Vec3(0, 0, 1));
	}

	/** All `NaN`. (NaN, NaN..) */
	static get NAN() {
		return new Mat3(
			new Vec3(Number.NaN, Number.NaN, Number.NaN),
			new Vec3(Number.NaN, Number.NaN, Number.NaN),
			new Vec3(Number.NaN, Number.NaN, Number.NaN),
		);
	}

	/**
	 * Creates a 3x3 matrix from 3 column vectors.
	 */
	static fromCols(xAxis: Vec3, yAxis: Vec3, zAxis: Vec3): Mat3 {
		return new Mat3(xAxis, yAxis, zAxis);
	}

	/**
	 * Creates a 3x3 matrix from an array of 9 values stored in column major order.
	 */
	static fromColsArray(
		m: [number, number, number, number, number, number, number, number, number],
	): Mat3 {
		return Mat3.new(m[0], m[1], m[2], m[3], m[4], m[5], m[6], m[7], m[8]);
	}

	/**
	 * Creates an array storing data in column major order.
	 */
	toColsArray(): [
		number,
		number,
		number,
		number,
		number,
		number,
		number,
		number,
		number,
	] {
		return [
			this.xAxis.x,
			this.xAxis.y,
			this.xAxis.z,
			this.yAxis.x,
			this.yAxis.y,
			this.yAxis.z,
			this.zAxis.x,
			this.zAxis.y,
			this.zAxis.z,
		];
	}
}
